const C=require('../../record-facts-core'),K=require('../../record-care-catalog');
const orders={"起床介助": ["起床に向けて声をかける", "短い言葉で声をかけた", "本人が寝返りを行う", "掛け物を外す介助を行った", "腰に手を添えて起き上がりを介助する", "端座位になる動作を介助する", "立ち上がりを介助する", "更衣を促す"], "就寝介助": ["就寝準備に向けて声をかける", "本人のペースを待った", "寝具を整える", "ベッドへの移乗を介助する", "横になる動作を介助する", "本人が掛け物を整える"], "トイレ介助": ["排泄に向けて声をかける", "トイレへの移動を介助する", "本人が衣類を下げる", "便座への移乗を介助する", "排泄中の見守りを行う", "排泄後の清拭を介助する", "本人が衣類を上げる", "手洗いを促す"], "更衣介助": ["更衣に向けて声をかける", "本人が衣類を選ぶ", "本人が衣類を脱ぐ", "右腕から袖を通す", "衣類を着る動作を介助する", "留め具の操作を介助する"], "入浴介助": ["入浴に向けて声をかける", "本人のペースを待った", "本人が上半身を洗う", "背部の洗身を介助する", "洗髪を介助する", "浴槽の出入りを介助する", "体を拭く動作を介助する", "着衣を介助する"], "食事介助": ["食事に向けて声をかける", "食器の位置を整える", "食事姿勢を整える", "本人が食具を操作する", "食事中の見守りを行う", "口腔ケアを促す"], "服薬介助・確認": ["服薬に向けて声をかける", "服薬の準備を介助する", "服薬用の水を準備する", "本人が薬を手に取る", "服薬の状況を確認する"], "口腔ケア": ["歯磨きに向けて声をかける", "歯ブラシを準備する", "本人が歯ブラシを持つ", "本人が歯を磨く", "口腔ケア中の見守りを行う", "本人が口をすすぐ"]};
const plan=service=>{const xs=K.choices(C,service);if(orders[service])return orders[service].map(value=>{const i=xs.find(i=>i.value===value);if(!i)throw Error('Missing catalog '+value);return i;});const out=[];for(const [cat,n]of [['prepare',2],['self',1],['work',3],['related',1],['method',1],['communication',1],['precaution',1]])out.push(...xs.filter(i=>i.category===cat).slice(0,n));return out;};
